bool debug_layer=false;
void require(bool v,const char* why){if(!v)throw std::runtime_error(why);}
void check(HRESULT hr,const std::source_location where=std::source_location::current()){if(FAILED(hr))throw std::runtime_error("Definition fixture HRESULT="+std::to_string(UINT(hr))+" line="+std::to_string(where.line()));}
void audit(ID3D11Device* device){if(!debug_layer)return;ComPtr<ID3D11InfoQueue> info;check(device->QueryInterface(IID_PPV_ARGS(&info)));for(UINT64 i=0;i<info->GetNumStoredMessagesAllowedByRetrievalFilter();++i){SIZE_T length=0;check(info->GetMessage(i,nullptr,&length));std::vector<uint8_t> bytes(length);auto* msg=reinterpret_cast<D3D11_MESSAGE*>(bytes.data());check(info->GetMessage(i,msg,&length));if(msg->Severity<=D3D11_MESSAGE_SEVERITY_WARNING){std::cerr<<msg->pDescription<<std::endl;throw std::runtime_error("Definition oracle emitted Debug Layer warning/error");}}}
template<class F>void rejects(F f,const char* text){try{f();}catch(const std::exception& e){require(std::string(e.what()).find(text)!=std::string::npos,e.what());return;}throw std::runtime_error("Expected definition refusal");}
template<class T>T desc(const FrozenObject& o){require(o.descriptor.size()>=sizeof(T),"Definition descriptor missing");T d{};memcpy(&d,o.descriptor.data(),sizeof d);return d;}
ComPtr<ID3DBlob> compile(const char* text,const char* profile){ComPtr<ID3DBlob> code,error;const auto hr=D3DCompile(text,strlen(text),"definition-oracle",nullptr,nullptr,"main",profile,0,0,&code,&error);if(FAILED(hr) && error)std::cerr<<static_cast<const char*>(error->GetBufferPointer())<<std::endl;check(hr);return code;}
struct Model {std::shared_ptr<const DeferredCommandList> list;ObjectId texture,rtv,vertices,constants,layout,vs,ps,cs,srv,uav,sampler,blend,depth,raster,output,geometry;};
void pixels(const std::vector<uint8_t>& bytes,const uint8_t* color){require(bytes.size()==8*8*4,"Output extent changed");for(size_t i=0;i<bytes.size();i+=4)require(!memcmp(bytes.data()+i,color,4),"Definition Draw pixels differ from oracle");}
std::vector<uint8_t> read_texture(ID3D11Device* device,ID3D11DeviceContext* context,ID3D11Texture2D* texture){
    D3D11_TEXTURE2D_DESC td{};texture->GetDesc(&td);require(td.Width==8 && td.Height==8 && td.Format==DXGI_FORMAT_R8G8B8A8_UNORM,"Unexpected definition texture");td.Usage=D3D11_USAGE_STAGING;td.BindFlags=td.MiscFlags=0;td.CPUAccessFlags=D3D11_CPU_ACCESS_READ;ComPtr<ID3D11Texture2D> staging;check(device->CreateTexture2D(&td,nullptr,&staging));context->CopyResource(staging.Get(),texture);D3D11_MAPPED_SUBRESOURCE mapped{};check(context->Map(staging.Get(),0,D3D11_MAP_READ,0,&mapped));std::vector<uint8_t> image(256);for(UINT y=0;y<8;++y)memcpy(image.data()+y*32,static_cast<uint8_t*>(mapped.pData)+y*mapped.RowPitch,32);context->Unmap(staging.Get(),0);return image;
}
