    auto* vb=vertices.Get();auto* cb=constants.Get();auto* rt=target.Get();auto* sv=srv.Get();auto* uv=uav.Get();auto* ss=sampler.Get();UINT stride=16,offset=0;D3D11_VIEWPORT viewport{0,0,8,8,0,1};context->VSSetShader(vs.Get(),nullptr,0);context->PSSetShader(ps.Get(),nullptr,0);context->CSSetShader(cs.Get(),nullptr,0);context->IASetInputLayout(layout.Get());context->IASetVertexBuffers(0,1,&vb,&stride,&offset);context->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);context->PSSetConstantBuffers(0,1,&cb);context->PSSetSamplers(0,1,&ss);context->CSSetShaderResources(0,1,&sv);context->CSSetUnorderedAccessViews(0,1,&uv,nullptr);context->OMSetRenderTargets(1,&rt,nullptr);context->OMSetBlendState(blend.Get(),nullptr,UINT(-1));context->OMSetDepthStencilState(depth.Get(),0);context->RSSetState(raster.Get());context->RSSetViewports(1,&viewport);context->Draw(3,0);context->Dispatch(4,1,1);
