int wmain(int argc,wchar_t** argv){try{bool hardware=false;for(int i=1;i<argc;++i){hardware|=std::wstring(argv[i])==L"--hardware";debug_layer|=std::wstring(argv[i])==L"--debug";}const auto model=capture(hardware);recreate(model);guards(hardware);require(object_status().at("active")==0 && metadata_status().at("alive")==0,"Definition test leaked native references");std::cout<<"Owned device/resource/view/shader/state/input/SO definitions recreated after source destruction; creation bytes remain distinct from GPU initial state\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
